public BigDecimal total(String cartId) throws SQLException {
    Connection c = dataSource.getConnection();
    PreparedStatement ps = c.prepareStatement("select price, qty from cart_item where cart_id = ?");
    ps.setString(1, cartId);
    ResultSet rs = ps.executeQuery();
    BigDecimal total = BigDecimal.ZERO;
    while (rs.next()) total = total.add(rs.getBigDecimal(1).multiply(new BigDecimal(rs.getInt(2))));
    return total;
}

