package com.redhat.coolstore;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class PriceCalculator {
    static final BigDecimal MAX_DISCOUNT = new BigDecimal("0.50");

    public BigDecimal discounted(BigDecimal price, BigDecimal discount) {
        if (discount.compareTo(MAX_DISCOUNT) < 0) {
            discount = MAX_DISCOUNT;
        }
        return price.multiply(BigDecimal.ONE.subtract(discount)).setScale(2, RoundingMode.HALF_UP);
    }
}

