package com.redhat.coolstore;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.inject.Inject;
import jakarta.persistence.EntityManager;
import java.util.List;

@ApplicationScoped
public class OrderHistoryService {
    @Inject EntityManager em;

    public List<OrderView> history(String customerId) {
        List<Order> orders = em.createQuery("from Order o where o.customerId = :c", Order.class)
            .setParameter("c", customerId).getResultList();
        return orders.stream()
            .map(o -> new OrderView(o.getId(), o.getItems().size(), o.getTotal()))
            .toList();
    }
}
